ALTER TABLE cms_studio_heads ADD COLUMN migration_id TEXT;
CREATE TABLE cms_cpu_migrations (id TEXT PRIMARY KEY, actor TEXT NOT NULL, origin TEXT NOT NULL, version INTEGER NOT NULL CHECK(version > 0), source_hash TEXT NOT NULL, source_project BLOB, build_key TEXT NOT NULL, expected_cache TEXT, project_hash TEXT NOT NULL, resources TEXT NOT NULL, artifact_hash TEXT NOT NULL, text_parts INTEGER NOT NULL CHECK(text_parts > 0), proof_parts INTEGER NOT NULL CHECK(proof_parts >= 0), reference_parts INTEGER NOT NULL CHECK(reference_parts >= 0), reference_count INTEGER NOT NULL CHECK(reference_count >= 0), stage_bytes INTEGER NOT NULL CHECK(stage_bytes > 0), planned_reads INTEGER NOT NULL CHECK(planned_reads >= 0), planned_writes INTEGER NOT NULL CHECK(planned_writes >= 0), budget_day TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), committed_at TEXT, state TEXT NOT NULL DEFAULT 'preparing' CHECK(state IN ('preparing','ready','committing','committed','aborted','rolling_back','rolled_back')));
CREATE INDEX cms_cpu_migration_expiry ON cms_cpu_migrations(actor,state,created_at,id);
CREATE TABLE cms_cpu_migration_rows (operation_id TEXT NOT NULL REFERENCES cms_cpu_migrations(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK(kind IN ('text','proof','references')), part INTEGER NOT NULL CHECK(part >= 0), body TEXT NOT NULL CHECK(length(CAST(body AS BLOB)) <= 1000000), PRIMARY KEY(operation_id,kind,part));
